    unsigned long StringLength;                                // +0x04
    unsigned long DataLength : 31;                             // +0x08
    bool          UseFastExtend : 1;                           // +0x0c
    bool operator==(const char* text) const;                   // 0x004115A0
};
struct CCharStringData {                                       // 17 bytes
    CBasicStringChar Data;                                     // +0x00
