        DragCamPos = heroPos - offset * CameraStringLength / (float)sqrt(lengthSq);
    else if (lengthSq < CameraCageRadius * CameraCageRadius)
        DragCamPos = heroPos - offset * CameraCageRadius / (float)sqrt(lengthSq);
}

